-- 대웅 원장(thynC_status_DW.xlsx '1. 거래처별 종합현황') 딜 전면 재적재 (2026-07-31)
-- 232건 = 레코드 원천 (사용자 확정). 기존 딜 전건 삭제 후 INSERT. 상태는 전부 '계약완료'.
-- 병원 매핑: 완전일치 187 + 확정 21 (2026-07-31 사용자 승인). 차수 = 병원 내 원장 순서(공사일 정렬).
BEGIN;
DELETE FROM sales_deals;

-- 프로젝트 재연결 (보수적 2규칙 — 환경 로컬 실행)
-- 규칙1: 병원+계약일 정확 일치 & 양쪽 모두 유일
UPDATE sales_deals d SET project_code = m.project_code FROM (
  SELECT d2.id, p.project_code FROM sales_deals d2
  JOIN projects p ON p.hospital_code=d2.hospital_code AND p.contract_date=d2.contract_date
  WHERE d2.contract_date IS NOT NULL
    AND (SELECT count(*) FROM projects px WHERE px.hospital_code=d2.hospital_code AND px.contract_date=d2.contract_date)=1
    AND (SELECT count(*) FROM sales_deals dx WHERE dx.hospital_code=d2.hospital_code AND dx.contract_date=d2.contract_date)=1
) m WHERE d.id=m.id AND d.project_code IS NULL;
-- 규칙2: 병원 내 딜 수 = 프로젝트 수 → 순서 페어링 (딜 차수 ↔ 프로젝트 orderNumber)
WITH dd AS (SELECT id, hospital_code, row_number() OVER (PARTITION BY hospital_code ORDER BY round_no) rn, count(*) OVER (PARTITION BY hospital_code) dc FROM sales_deals WHERE project_code IS NULL),
     pp AS (SELECT project_code, hospital_code, row_number() OVER (PARTITION BY hospital_code ORDER BY order_number, project_code) rn, count(*) OVER (PARTITION BY hospital_code) pc FROM projects p WHERE NOT EXISTS (SELECT 1 FROM sales_deals sd WHERE sd.project_code=p.project_code))
UPDATE sales_deals SET project_code = pp.project_code FROM dd JOIN pp ON pp.hospital_code=dd.hospital_code AND pp.rn=dd.rn AND dd.dc=pp.pc WHERE sales_deals.id=dd.id;
COMMIT;
-- 검증
SELECT count(*) AS 딜수, count(DISTINCT hospital_code) AS 병원수, sum(daewoong_amount_total) AS 계약금액합, sum(daewoong_device_count) AS 디바이스합, count(project_code) AS 프로젝트연결 FROM sales_deals;
